function highlight(line,path,commentState={block:false}){const ext=path.split('.').pop();let re;if(['xml','html'].includes(ext)){re=/(<!--[\s\S]*?-->|<\/?[\w:-]+|\/?>|"[^"\n]*"|'[^'\n]*'|\b[\w:-]+(?==))/g;}else{re=/(\/\/.*$|\/\*.*?(?:\*\/|$)|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`[^`]*`|@[A-Za-z][\w.]*|\b(?:package|import|public|private|protected|class|interface|record|enum|extends|implements|static|final|void|new|return|if|else|throw|throws|try|catch|true|false|null|this|super|const|let|var|function|async|await|export|default|from|for|while|switch|case|break|continue|instanceof)\b|\b\d+(?:\.\d+)?\b|\b[A-Z][A-Za-z0-9_]*\b|\b[a-zA-Z_$][\w$]*(?=\s*\())/g;}
let result='',pos=0,m;if(commentState.block){const end=line.indexOf('*/');if(end<0)return `<span class="syn-comment">${esc(line)}</span>`;result=`<span class="syn-comment">${esc(line.slice(0,end+2))}</span>`;pos=end+2;re.lastIndex=pos;commentState.block=false;}while((m=re.exec(line))){if(m.index<pos)continue;result+=esc(line.slice(pos,m.index));const v=m[0];let cls;if(['xml','html'].includes(ext)){cls=v.startsWith('<!--')?'syn-comment':v[0]==='"'||v[0]==="'"?'syn-str':v.startsWith('<')||v==='>'||v==='/>'?'syn-tag':'syn-prop';}else{cls=v.startsWith('//')||v.startsWith('/*')?'syn-comment':/^['"`]/.test(v)?'syn-str':v[0]==='@'?'syn-annotation':/^\d/.test(v)?'syn-num':/^[A-Z]/.test(v)?'syn-type':/^(package|import|public|private|protected|class|interface|record|enum|extends|implements|static|final|void|new|return|if|else|throw|throws|try|catch|true|false|null|this|super|const|let|var|function|async|await|export|default|from|for|while|switch|case|break|continue|instanceof)$/.test(v)?'syn-key':'syn-fn';if(v.startsWith('/*')&&!v.endsWith('*/'))commentState.block=true;}result+=`<span class="${cls}">${esc(v)}</span>`;pos=m.index+v.length;}result+=esc(line.slice(pos));if(['yml','yaml','properties','sh','sql','md'].includes(ext)&&/^\s*#/.test(line))return `<span class="syn-comment">${esc(line)}</span>`;return result;}
