function changesCard(changes,sid,turn,overall=false){if(!changes.length)return'';return `<div class="changes-card"><div class="changes-heading">${changes.length} files changed <span class="muted">· ${overall?'Entire session':'Since last turn'}</span><button class="review-button" data-action="review-turn" data-session="${sid}" data-turn="${turn||''}">Review</button></div>${changes.map(ch=>`<button class="change-row" data-action="chat-diff" data-session="${sid}" data-turn="${turn||''}" data-path="${esc(ch.path)}" title="Open diff: ${esc(ch.path)}">${icon('java')}<span class="change-name">${esc(base(ch.path))}</span>${stats(ch)}</button>`).join('')}</div>`}
function activityItem(a){if(a.type==='message'){if(a.phase==='Final'||!a.text.trim())return'';const title=a.role==='Runtime'?(a.text.match(/\*\*([^*]+)\*\*/)?.[1]||'Agent reasoning'):'Agent update';return `<details class="activity-entry"><summary>${icon('chevron')}<span class="activity-title">${esc(title)}</span><time>${time(a.timestamp)}</time></summary><div class="activity-text markdown">${markdown(a.text)}</div></details>`;}const fail=a.status==='failed';return `<details class="activity-entry"><summary>${icon(a.kind==='edit'?'diff':a.kind==='execute'?'terminal':a.kind==='search'?'search':'file')}<span class="activity-title">${esc(a.title||a.id)}</span><span class="tool-status ${fail?'red':'green'}">${fail?'Failed':'✓'}</span><time>${time(a.timestamp)}</time></summary>${a.rawInput?`<div class="tool-command">${esc(typeof a.rawInput==='string'?a.rawInput:JSON.stringify(a.rawInput,null,2))}</div>`:''}${a.output?`<pre class="tool-output">${esc(a.output)}</pre>`:'<div class="activity-text muted">No recorded terminal output.</div>'}${(a.content||[]).filter(c=>c.type==='diff').map(c=>`<pre class="tool-output">${esc(c.patch?.text||'')}</pre>`).join('')}</details>`;}
